v=$(python -c "import sys,json;d=json.load(sys.stdin);tp=d.get('transcript_path','');import io
last=''
for line in io.open(tp,encoding='utf-8',errors='replace') if tp else []:
    try:
        import json as j;m=j.loads(line)
    except Exception:continue
    if m.get('type')=='assistant':
        c=m.get('message',{}).get('content',[])
        for b in c:
            if isinstance(b,dict) and b.get('type')=='text' and b.get('text'):last=b['text']
print((last.strip().splitlines() or ['turn complete'])[0][:150])" 2>/dev/null || echo 'turn complete'); curl -s -m 6 -d "CC DONE: $v" -H "Tags: white_check_mark" https://ntfy.sh/omi-livev4-omqs-x7k3q9v2 >/dev/null 2>&1 || true
